#!/bin/bash
# Generated by reef-eval's EdgeBench converter. Runs in the SEPARATE verifier
# container (built from the judge image). Harbor re-materializes the declared
# submission artifacts at their original paths before this script runs; the
# checks below just make a missing submission loud.
set -uo pipefail
mkdir -p /logs/verifier

[ -e "/home/workspace/exchange-core/src/main" ] || echo "WARNING: submission missing: /home/workspace/exchange-core/src/main"
[ -e "/home/workspace/exchange-core/pom.xml" ] || echo "WARNING: submission missing: /home/workspace/exchange-core/pom.xml"
[ -e "/home/workspace/exchange-core/.mvn" ] || echo "WARNING: submission missing: /home/workspace/exchange-core/.mvn"

cd /home/workspace/exchange-core
OUT=$(cd /home/workspace/exchange-core && python3 /tmp/eval_exchange_core.py 2>&1)
EC=$?
echo "$OUT" | tail -40
printf '%s' "$OUT" | python3 /tests/parse_score.py
echo "eval exit code: $EC" > /logs/verifier/eval_exit_code.txt
